/**
 * VitalLens Storage - History Persistence Store
 *
 * Persists vitals scan records into IndexedDB and localStorage with full CRUD operations and trend queries.
 * Stores real user-scanned data dynamically generated by the camera signal processor.
 */

import {
  saveRecordDB,
  getAllRecordsDB,
  deleteRecordDB,
  clearAllRecordsDB,
} from './vitalsDb';
import type { VitalsRecord } from './vitalsDb';
import {
  saveRecordToSupabase,
  deleteRecordFromSupabase,
  fetchRecordsFromSupabase,
} from './supabaseService';
import { isSupabaseConfigured } from './supabaseClient';

export type { VitalsRecord } from './vitalsDb';

const STORAGE_KEY = 'vitallens_scan_history_v1';

export async function fetchAllHistoryAsync(): Promise<VitalsRecord[]> {
  const localRecords = await getAllRecordsDB();

  // If external Supabase DB is configured, merge cloud records
  if (isSupabaseConfigured()) {
    try {
      const remote = await fetchRecordsFromSupabase();
      if (remote.data && remote.data.length > 0) {
        const localMap = new Map(localRecords.map((r) => [r.id, r]));
        let hasNew = false;
        for (const rem of remote.data) {
          if (!localMap.has(rem.id)) {
            await saveRecordDB(rem);
            localMap.set(rem.id, rem);
            hasNew = true;
          }
        }
        if (hasNew) {
          const merged = Array.from(localMap.values()).sort((a, b) => b.timestamp - a.timestamp);
          try {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(merged));
          } catch {}
          return merged;
        }
      }
    } catch {
      // Offline or network issue, fallback to local records
    }
  }

  return localRecords;
}

export function getScanHistory(): VitalsRecord[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    return JSON.parse(raw);
  } catch {
    return [];
  }
}

export function saveScanRecord(record: any): VitalsRecord {
  const newRecord: VitalsRecord = {
    ...record,
    id: record.id || ('scan-' + Date.now() + '-' + Math.random().toString(36).substring(2, 7)),
    timestamp: record.timestamp || Date.now(),
  };

  // 1. Dual save to native on-device IndexedDB
  saveRecordDB(newRecord).catch(() => {});

  // 2. Asynchronously replicate to external Supabase PostgreSQL database
  saveRecordToSupabase(newRecord).catch(() => {});

  // 3. Fallback cache in localStorage
  const history = getScanHistory();
  const filtered = history.filter((item: any) => item.id !== newRecord.id);
  const updated = [newRecord, ...filtered];
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  } catch {}
  return newRecord;
}

export function deleteScanRecord(id: string) {
  // Delete from local IndexedDB
  deleteRecordDB(id).catch(() => {});

  // Delete from external Supabase DB
  deleteRecordFromSupabase(id).catch(() => {});

  const history = getScanHistory();
  const updated = history.filter((item: any) => item.id !== id);
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  } catch {}
  return updated;
}

export function clearAllScanHistory() {
  clearAllRecordsDB().catch(() => {});
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {}
}

export interface PersonalBaseline {
  sevenDayAvgHr: number;
  sevenDayAvgHrv: number;
  sevenDayAvgSpo2: number;
  sevenDayAvgRr: number;
  sampleCount: number;
  hrDelta: number; // latest - baseline
  hrvDelta: number;
}

export function calculatePersonalBaseline(records: any[]): PersonalBaseline | null {
  if (!records || records.length === 0) return null;

  const now = Date.now();
  const sevenDaysAgo = now - 7 * 24 * 60 * 60 * 1000;
  const recent = records.filter((r) => r.timestamp >= sevenDaysAgo);
  const sample = recent.length > 0 ? recent : records.slice(0, 10);

  const avgHr = Math.round(sample.reduce((sum, r) => sum + (r.heartRate || 72), 0) / sample.length);
  const avgHrv = Math.round(sample.reduce((sum, r) => sum + (r.hrvRmssd || 40), 0) / sample.length);
  const avgSpo2 = Math.round(sample.reduce((sum, r) => sum + (r.spo2 || 98), 0) / sample.length);
  const avgRr = Math.round(sample.reduce((sum, r) => sum + (r.respiratoryRate || 15), 0) / sample.length);

  const latest = records[0];
  const hrDelta = latest ? latest.heartRate - avgHr : 0;
  const hrvDelta = latest && latest.hrvRmssd ? latest.hrvRmssd - avgHrv : 0;

  return {
    sevenDayAvgHr: avgHr,
    sevenDayAvgHrv: avgHrv,
    sevenDayAvgSpo2: avgSpo2,
    sevenDayAvgRr: avgRr,
    sampleCount: sample.length,
    hrDelta,
    hrvDelta,
  };
}
